def find_battery(charges, target):
    first = 0
    last = len(charges) - 1
    comparisons = 0
    while first <= last:
        middle = (first + last) // 2
        charge = charges[middle]
        comparisons += 1
        matches = charge == target
        if matches:
            return [middle, comparisons]
        if charge < target:
            first = middle + 1
        else:
            last = middle - 1
    return [-1, comparisons]
